        assertEquals(JAVA_15, get("15"), "15 failed");
        assertEquals(JAVA_16, get("16"), "16 failed");
        assertEquals(JAVA_17, get("17"), "17 failed");
        assertEquals(JAVA_RECENT, get("1.10"), "1.10 failed");
