@Override
    public char charAt(final int index) {
        if (index < 0 || index >= length()) {
            throw new StringIndexOutOfBoundsException(index);
        }
        return buffer[index];
    }

public static String randomGraph(final int count) {
        return random(count, 33, 126, false, false);
