        final String exp = getClassPrefix(customer) + "[" + BR
                   + "  accounts=<null>," + BR
                   + "  bank=" + getClassPrefix(bank) + "[" + BR
                   + "    name=ASF Bank" + BR
                   + "  ]," + BR
